import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

@RestController
public class ProfileController {

    // PATCH /profiles/3，只传需要修改的字段
    @PatchMapping("/profiles/{id}")
    public Profile patch(@PathVariable Long id, @RequestBody Map<String, Object> patch) {
        Profile old = new Profile(id, "小明", "xiaoming@example.com");
        if (patch.containsKey("nickname")) {
            old = old.withNickname((String) patch.get("nickname"));
        }
        return old;
    }

    public record Profile(Long id, String nickname, String email) {
        public Profile withNickname(String nickname) {
            return new Profile(id, nickname, email);
        }
    }
}

