import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;

@Controller
public class RegisterController {

    // 每个请求前执行：预置城市下拉选项
    @ModelAttribute("cities")
    public String[] cities() {
        return new String[]{"北京", "上海", "广州"};
    }

    // GET /register 显示表单，user 是新对象
    @GetMapping("/register")
    public String form(@ModelAttribute("user") UserForm user, Model model) {
        model.addAttribute("user", user);
        return "register";
    }

    // POST /register 表单提交，字段按参数名绑定到 user
    @PostMapping("/register")
    public String submit(@ModelAttribute("user") UserForm user) {
        return "redirect:/register?ok";
    }

    public static class UserForm {
        private String username;
        private String city;
        public String getUsername() { return username; }
        public void setUsername(String username) { this.username = username; }
        public String getCity() { return city; }
        public void setCity(String city) { this.city = city; }
    }
}

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestAttribute;
import org.springframework.web.bind.annotation.RestController;
