import jakarta.servlet.http.HttpSession;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.SessionAttribute;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/account")
public class AccountController {

    // 登录接口：手动把用户放进 session
    @GetMapping("/login")
    public String login(HttpSession session) {
        session.setAttribute("loginUser", "小明");
        return "logged-in";
    }

    // 后续请求直接取 session 属性
    @GetMapping("/info")
    public String info(@SessionAttribute("loginUser") String user) {
        return "user=" + user;
    }

    // 未登录也能访问：required=false 时取到 null
    @GetMapping("/optional")
    public String optional(@SessionAttribute(name = "loginUser", required = false) String user) {
        return "user=" + user;
    }
}

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.SessionAttributes;
import org.springframework.web.bind.support.SessionStatus;

@Controller
@SessionAttributes("cart")   // 模型里的 cart 会存进 session
public class CartController {

    @ModelAttribute("cart")
    public Cart cart() {
        return new Cart();       // 首次创建，之后从 session 取回
    }

    @PostMapping("/cart/add")
    public String add(@ModelAttribute("cart") Cart cart, String item) {
        cart.add(item);
        return "redirect:/cart";
    }

    @GetMapping("/cart/clear")
    public String clear(SessionStatus status) {
        status.setComplete();    // 请求结束后从 session 移除
        return "redirect:/cart";
    }

    public static class Cart {
        private final java.util.List<String> items = new java.util.ArrayList<>();
        public void add(String item) { items.add(item); }
        public java.util.List<String> getItems() { return items; }
    }
}

import org.springframework.beans.propertyeditors.CustomDateEditor;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.WebDataBinder;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.InitBinder;
import org.springframework.web.bind.annotation.ModelAttribute;

import java.text.SimpleDateFormat;
import java.util.Date;

@Controller
public class ProfileController {

    @InitBinder
    public void initBinder(WebDataBinder binder) {
        // 禁止前端通过表单直接修改 id、role
        binder.setDisallowedFields("id", "role");
        // yyyy-MM-dd 字符串转 Date
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        sdf.setLenient(false);
        binder.registerCustomEditor(Date.class, new CustomDateEditor(sdf, true));
    }

    @GetMapping("/profile/edit")
    public String edit(@ModelAttribute("profile") ProfileForm form) {
        return "profile/edit";
    }

    public static class ProfileForm {
        private Long id;
        private String role;
        private Date birthday;
        public Long getId() { return id; }
        public void setId(Long id) { this.id = id; }
        public String getRole() { return role; }
        public void setRole(String role) { this.role = role; }
        public Date getBirthday() { return birthday; }
        public void setBirthday(Date birthday) { this.birthday = birthday; }
    }
}

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.servlet.ModelAndView;

// 对所有 @Controller 生效
@ControllerAdvice
public class GlobalControllerAdvice {

    // 每个控制器方法执行前都往模型里放站点信息
    @ModelAttribute("siteName")
    public String siteName() {
        return "小明的技术站";
    }

    // 未捕获的 IllegalStateException 统一渲染错误页
    @ExceptionHandler(IllegalStateException.class)
    public ModelAndView handleState(IllegalStateException ex) {
        ModelAndView mav = new ModelAndView("error/500");
        mav.addObject("message", ex.getMessage());
        return mav;
    }
}

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class ApiExceptionAdvice {

    // 参数非法 → 400，返回统一 JSON 结构
    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<ApiError> handleBadRequest(IllegalArgumentException ex) {
        return ResponseEntity.badRequest()
                .body(new ApiError(400, ex.getMessage()));
    }

    // 兜底 → 500，别把堆栈信息返回给前端
    @ExceptionHandler(Exception.class)
    public ResponseEntity<ApiError> handleAll(Exception ex) {
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(new ApiError(500, "服务器开小差了"));
    }

    public record ApiError(int code, String message) {
    }
}

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ItemController {

    @GetMapping("/items/{id}")
    public String item(@PathVariable Long id) {
        if (id > 100) {
            throw new ItemNotFoundException(id);
        }
        return "item-" + id;
    }

    // 只处理本控制器的 ItemNotFoundException
    @ExceptionHandler(ItemNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public String notFound(ItemNotFoundException ex) {
        return "找不到商品：" + ex.getId();
    }

    public static class ItemNotFoundException extends RuntimeException {
        private final Long id;
        public ItemNotFoundException(Long id) {
            super("item " + id);
            this.id = id;
        }
        public Long getId() { return id; }
    }
}

