import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class RegisterController {

    @PostMapping("/register")
    public String register(@Valid @RequestBody RegisterForm form) {
        return "mail to " + form.email();
    }

    public record RegisterForm(
            @NotBlank(message = "邮箱不能为空")
            @Email(message = "邮箱格式不正确") String email) {
    }
}

import jakarta.validation.Valid;
import jakarta.validation.constraints.Past;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import java.time.LocalDate;

@RestController
public class BirthController {

    @PostMapping("/birthdays")
    public String save(@Valid @RequestBody BirthForm form) {
        return "birthday " + form.birthday();
    }

    public record BirthForm(
            // 必须是今天之前的日期
            @Past(message = "生日不能是未来时间") LocalDate birthday) {
    }
}

import jakarta.validation.Valid;
import jakarta.validation.constraints.Future;
import jakarta.validation.constraints.NotNull;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import java.time.LocalDateTime;

@RestController
public class BookingController {

    @PostMapping("/bookings")
    public String book(@Valid @RequestBody BookingForm form) {
        return "booked at " + form.startAt();
    }

    public record BookingForm(
            @NotNull(message = "预约时间不能为空")
            @Future(message = "预约时间必须在未来") LocalDateTime startAt) {
    }
}

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import java.math.BigDecimal;

@RestController
public class TransferController {

    @PostMapping("/transfers")
    public String transfer(@Valid @RequestBody TransferForm form) {
        return "transfer " + form.amount();
    }

    public record TransferForm(
            @NotNull(message = "金额不能为空")
            @Positive(message = "转账金额必须大于 0")
            BigDecimal amount,

            // 允许 0 的场景用 @PositiveOrZero
            @Positive(message = "数量必须大于 0") int quantity) {
    }
}
